public class Main {
    static int n, k;
    static int[] segments;
    static int count = 0;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        segments = new int[n];
        for (int i = 0; i < n; i++) {
            segments[i] = sc.nextInt();
        }
        k = sc.nextInt();

        combination(new int[k], 0, 0);
        System.out.println(count);
    }

    static void combination(int[] selected, int start, int depth) {
        if (depth == k) {
            int[] sides = new int[k];
            for (int i = 0; i < k; i++) {
                sides[i] = segments[selected[i]];
            }
            Arrays.sort(sides);

            int sum = 0;
            for (int i = 0; i < k - 1; i++) {
                sum += sides[i];
            }

            if (sum > sides[k - 1]) {
                count++;
            }
            return;
        }

        for (int i = start; i < n; i++) {
            selected[depth] = i;
            combination(selected, i + 1, depth + 1);
        }
    }
}

