public class Main {
    static class State {
        int zeros, ones, turns;
        State(int z, int o, int t) {
            zeros = z; ones = o; turns = t;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int k = sc.nextInt();

        if (a == 0 && b == 0) {
            System.out.println(0);
            return;
        }

        Map<String, Integer> visited = new HashMap<>();
        Queue<State> queue = new LinkedList<>();
        queue.offer(new State(a, b, 0));
        visited.put(a + "," + b, 0);

        int result = -1;

        while (!queue.isEmpty()) {
            State curr = queue.poll();

            if (curr.zeros == 0) {
                result = curr.turns;
                break;
            }

            for (int flipZeros = 0; flipZeros <= Math.min(curr.zeros, k); flipZeros++) {
                int flipOnes = k - flipZeros;
                if (flipOnes > curr.ones) continue;

                int newZeros = curr.zeros - flipZeros + flipOnes;
                int newOnes = curr.ones + flipZeros - flipOnes;

                if (newZeros < 0 || newOnes < 0) continue;

                String key = newZeros + "," + newOnes;
                if (!visited.containsKey(key) || visited.get(key) > curr.turns + 1) {
                    visited.put(key, curr.turns + 1);
                    queue.offer(new State(newZeros, newOnes, curr.turns + 1));
                }
            }
        }

        System.out.println(result);
    }
}

