public class Main {
    static boolean[] isPrime(int n) {
        boolean[] sieve = new boolean[n + 1];
        for (int i = 2; i <= n; i++) sieve[i] = true;

        for (int i = 2; i * i <= n; i++) {
            if (sieve[i]) {
                for (int j = i * i; j <= n; j += i) {
                    sieve[j] = false;
                }
            }
        }
        return sieve;
    }

    static int countPrimeFactors(int n) {
        int count = 0;
        for (int d = 2; d * d <= n; d++) {
            while (n % d == 0) {
                count++;
                n /= d;
            }
        }
        if (n > 1) count++;
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();

        boolean[] prime = isPrime(100000);

        int result = 0;
        for (int num = a; num <= b; num++) {
            int factorCount = countPrimeFactors(num);
            if (factorCount < prime.length && prime[factorCount]) {
                result++;
            }
        }

        System.out.println(result);
    }
}

