        dp.put(0, 0);

        for (int block : blocks) {
            Map<Integer, Integer> newDp = new HashMap<>(dp);

            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int diff = entry.getKey();
                int height = entry.getValue();

                // Add to taller
                int newDiff = diff + block;
                int newHeight = height + block;
                newDp.put(newDiff, Math.max(newDp.getOrDefault(newDiff, 0), newHeight));

                // Add to shorter
                if (diff >= block) {
                    newDiff = diff - block;
                    newHeight = height + block;
                } else {
                    newDiff = block - diff;
                    newHeight = height + diff;
                }
                newDp.put(newDiff, Math.max(newDp.getOrDefault(newDiff, 0), newHeight));
            }

            dp = newDp;
        }

        System.out.println(dp.getOrDefault(0, -1));
    }
